@using sv_808687ea18c2457cae0279030669c6e5.Services
@inject ISettingsService SettingsService

<h4 class="mb-4">Profile</h4>

@if (_profile is null)
{
    <p class="text-muted">Loading profile…</p>
}
else
{
    @if (_statusMessage is not null)
    {
        <div class="alert alert-success alert-dismissible" role="alert">
            @_statusMessage
            <button type="button" class="btn-close" @onclick="() => _statusMessage = null"></button>
        </div>
    }

    <div class="row">
        <div class="col-md-8">
            <div class="mb-3">
                <label class="form-label">Display Name</label>
                <input type="text" class="form-control" @bind="_displayName" />
            </div>
            <div class="mb-3">
                <label class="form-label">Email</label>
                <input type="email" class="form-control" @bind="_email" />
            </div>
            <div class="mb-3">
                <label class="form-label">Bio</label>
                <textarea class="form-control" rows="4" @bind="_bio"></textarea>
            </div>
        </div>
        <div class="col-md-4">
            <div class="text-center">
                <label class="form-label d-block">Avatar Preview</label>
                <div class="border rounded d-flex align-items-center justify-content-center mb-2"
                     style="width: 120px; height: 120px; margin: 0 auto; overflow: hidden; background: var(--bs-gray-100);">
                    @if (!string.IsNullOrWhiteSpace(_profile.AvatarUrl))
                    {
                        <img src="@_profile.AvatarUrl" alt="Avatar" style="max-width: 100%; max-height: 100%; object-fit: cover;" />
                    }
                    else
                    {
                        <span class="text-muted" style="font-size: 3rem;">👤</span>
                    }
                </div>
                <small class="text-muted text-break">@_profile.AvatarUrl</small>
            </div>
        </div>
    </div>

    <div class="d-flex gap-2 mt-3">
        <button class="btn btn-primary" @onclick="SaveChanges" disabled="@_isSaving">
            @(_isSaving ? "Saving…" : "Save Changes")
        </button>
        <button class="btn btn-outline-secondary" @onclick="DiscardChanges" disabled="@_isSaving">
            Discard Changes
        </button>
    </div>
}

@code {
    private UserProfile? _profile;
    private string _displayName = "";
    private string _email = "";
    private string _bio = "";
    private string? _statusMessage;
    private bool _isSaving;

    protected override async Task OnInitializedAsync()
    {
        await LoadProfile();
    }

    private async Task LoadProfile()
    {
        _profile = await SettingsService.GetProfileAsync();
        PopulateFields();
    }

    private void PopulateFields()
    {
        if (_profile is null) return;
        _displayName = _profile.DisplayName;
        _email = _profile.Email;
        _bio = _profile.Bio;
    }

    private async Task SaveChanges()
    {
        if (_profile is null) return;
        _isSaving = true;
        try
        {
            var updated = _profile with { DisplayName = _displayName, Email = _email, Bio = _bio };
            await SettingsService.SaveProfileAsync(updated);
            _profile = updated;
            _statusMessage = "Profile saved successfully!";
        }
        finally
        {
            _isSaving = false;
        }
    }

    private void DiscardChanges()
    {
        PopulateFields();
        _statusMessage = null;
    }
}

@using sv_808687ea18c2457cae0279030669c6e5.Services
@inject ISettingsService SettingsService

<h4 class="mb-4">Notifications</h4>

@if (_prefs is null)
{
    <p class="text-muted">Loading notification preferences…</p>
}
else
{
    @if (_statusMessage is not null)
    {
        <div class="alert alert-success alert-dismissible" role="alert">
            @_statusMessage
            <button type="button" class="btn-close" @onclick="() => _statusMessage = null"></button>
        </div>
    }

    <div class="mb-4">
        <h6>General</h6>
        <div class="form-check form-switch mb-2">
            <input class="form-check-input" type="checkbox" role="switch" id="emailNotif"
                   checked="@_emailNotifications"
                   @onchange="e => _emailNotifications = (bool)e.Value!" />
            <label class="form-check-label" for="emailNotif">Email Notifications</label>
        </div>
        <div class="form-check form-switch mb-2">
            <input class="form-check-input" type="checkbox" role="switch" id="pushNotif"
                   checked="@_pushNotifications"
                   @onchange="e => _pushNotifications = (bool)e.Value!" />
            <label class="form-check-label" for="pushNotif">Push Notifications</label>
        </div>
        <div class="form-check form-switch mb-2">
            <input class="form-check-input" type="checkbox" role="switch" id="weeklyDigest"
                   checked="@_weeklyDigest"
                   @onchange="e => _weeklyDigest = (bool)e.Value!" />
            <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
        </div>
    </div>

    <div class="mb-4">
        <h6>Muted Channels</h6>
        @if (_channels.Count == 0)
        {
            <p class="text-muted">No channels available.</p>
        }
        else
        {
            @foreach (var channel in _channels)
            {
                <div class="form-check mb-1">
                    <input class="form-check-input" type="checkbox" id="@($"ch-{channel.Name}")"
                           checked="@channel.IsMuted"
                           @onchange="e => channel.IsMuted = (bool)e.Value!" />
                    <label class="form-check-label" for="@($"ch-{channel.Name}")">@channel.Name</label>
                </div>
            }
        }
    </div>

    <button class="btn btn-primary" @onclick="SavePreferences" disabled="@_isSaving">
        @(_isSaving ? "Saving…" : "Save Preferences")
    </button>
}

@code {
    private NotificationPrefs? _prefs;
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private List<ChannelState> _channels = [];
    private string? _statusMessage;
    private bool _isSaving;

    protected override async Task OnInitializedAsync()
    {
        _prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = _prefs.EmailNotifications;
        _pushNotifications = _prefs.PushNotifications;
        _weeklyDigest = _prefs.WeeklyDigest;
        _channels = _prefs.MutedChannels
            .Select(c => new ChannelState { Name = c, IsMuted = true })
            .ToList();
    }

    private async Task SavePreferences()
    {
        _isSaving = true;
        try
        {
            var mutedChannels = _channels.Where(c => c.IsMuted).Select(c => c.Name).ToList();
            var updated = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, mutedChannels);
            await SettingsService.SaveNotificationPrefsAsync(updated);
            _prefs = updated;
            _statusMessage = "Notification preferences saved!";
        }
        finally
        {
            _isSaving = false;
        }
    }

    private class ChannelState
    {
        public string Name { get; set; } = "";
        public bool IsMuted { get; set; }
    }
}

@using sv_808687ea18c2457cae0279030669c6e5.Services
@inject ISettingsService SettingsService

<h4 class="mb-4">Security</h4>

@if (_settings is null)
{
    <p class="text-muted">Loading security settings…</p>
}
else
{
    @if (_statusMessage is not null)
    {
        <div class="alert @(_isError ? "alert-danger" : "alert-success") alert-dismissible" role="alert">
            @_statusMessage
            <button type="button" class="btn-close" @onclick="() => _statusMessage = null"></button>
        </div>
    }

    <div class="mb-4">
        <ChangePasswordPanel OnChangePassword="HandleChangePassword" />
    </div>

    <div class="mb-4">
        <h6>Two-Factor Authentication</h6>
        <div class="d-flex align-items-center gap-3">
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" role="switch" id="twoFactor"
                       checked="@_twoFactorEnabled"
                       @onchange="e => _twoFactorEnabled = (bool)e.Value!" />
                <label class="form-check-label" for="twoFactor">Enable Two-Factor Authentication</label>
            </div>
            <span class="badge @(_twoFactorEnabled ? "bg-success" : "bg-secondary")">
                @(_twoFactorEnabled ? "Enabled" : "Disabled")
            </span>
        </div>
        @if (_settings.LastPasswordChange.HasValue)
        {
            <small class="text-muted d-block mt-2">
                Last password change: @_settings.LastPasswordChange.Value.ToString("MMMM d, yyyy")
            </small>
        }
    </div>

    <div class="mb-4">
        <h6>Active Sessions</h6>
        <div class="table-responsive">
            <table class="table table-striped align-middle">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in _sessions)
                    {
                        var isCurrentSession = session == _sessions.FirstOrDefault();
                        <tr>
                            <td>
                                @session.Device
                                @if (isCurrentSession)
                                {
                                    <span class="badge bg-info ms-1">Current</span>
                                }
                            </td>
                            <td>@session.Location</td>
                            <td>@session.LastActive.ToString("g")</td>
                            <td>
                                @if (!isCurrentSession)
                                {
                                    <button class="btn btn-outline-danger btn-sm"
                                            @onclick="() => _sessionToRevoke = session">
                                        Revoke
                                    </button>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    </div>

    <RevokeSessionDialog Session="_sessionToRevoke"
                         OnConfirm="ConfirmRevoke"
                         OnCancel="() => _sessionToRevoke = null" />
}

@code {
    private SecuritySettings? _settings;
    private List<ActiveSession> _sessions = [];
    private bool _twoFactorEnabled;
    private ActiveSession? _sessionToRevoke;
    private string? _statusMessage;
    private bool _isError;

    protected override async Task OnInitializedAsync()
    {
        await LoadSettings();
    }

    private async Task LoadSettings()
    {
        _settings = await SettingsService.GetSecuritySettingsAsync();
        _sessions = _settings.Sessions.ToList();
        _twoFactorEnabled = _settings.TwoFactorEnabled;
    }

    private async Task HandleChangePassword((string CurrentPassword, string NewPassword) args)
    {
        await SettingsService.ChangePasswordAsync(args.CurrentPassword, args.NewPassword);
    }

    private async Task ConfirmRevoke()
    {
        if (_sessionToRevoke is null) return;

        try
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            _sessions.Remove(_sessionToRevoke);
            _statusMessage = $"Session on \"{_sessionToRevoke.Device}\" has been revoked.";
            _isError = false;
        }
        catch (Exception ex)
        {
            _statusMessage = $"Failed to revoke session: {ex.Message}";
            _isError = true;
        }
        finally
        {
            _sessionToRevoke = null;
        }
    }
}

@using sv_808687ea18c2457cae0279030669c6e5.Services
@inject ISettingsService SettingsService

<h4 class="mb-4">Appearance</h4>

@if (_settings is null)
{
    <p class="text-muted">Loading appearance settings…</p>
}
else
{
    @if (_statusMessage is not null)
    {
        <div class="alert alert-success alert-dismissible" role="alert">
            @_statusMessage
            <button type="button" class="btn-close" @onclick="() => _statusMessage = null"></button>
        </div>
    }

    <div class="row">
        <div class="col-md-7">
            <div class="mb-4">
                <h6>Theme</h6>
                @foreach (var theme in new[] { "Light", "Dark", "System" })
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="theme" id="@($"theme-{theme}")"
