{"file_text": "@using sv_808687ea18c2457cae0279030669c6e5.Services
@inject ISettingsService SettingsService

<h4 class="mb-4">Security</h4>

@if (_settings is null)
{
    <p class="text-muted">Loading security settings…</p>
}
else
{
    @if (_statusMessage is not null)
    {
        <div class="alert @(_isError ? "alert-danger" : "alert-success") alert-dismissible" role="alert">
            @_statusMessage
            <button type="button" class="btn-close" @onclick="() => _statusMessage = null"></button>
        </div>
    }

    <div class="mb-4">
        <ChangePasswordPanel OnChangePassword="HandleChangePassword" />
    </div>

    <div class="mb-4">
        <h6>Two-Factor Authentication</h6>
        <div class="d-flex align-items-center gap-3">
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" role="switch" id="twoFactor"
                       checked="@_twoFactorEnabled"
                       @onchange="e => _twoFactorEnabled = (bool)e.Value!" />
                <label class="form-check-label" for="twoFactor">Enable Two-Factor Authentication</label>
            </div>
            <span class="badge @(_twoFactorEnabled ? "bg-success" : "bg-secondary")">
                @(_twoFactorEnabled ? "Enabled" : "Disabled")
            </span>
        </div>
        @if (_settings.LastPasswordChange.HasValue)
        {
            <small class="text-muted d-block mt-2">
                Last password change: @_settings.LastPasswordChange.Value.ToString("MMMM d, yyyy")
            </small>
        }
    </div>

    <div class="mb-4">
        <h6>Active Sessions</h6>
        <div class="table-responsive">
            <table class="table table-striped align-middle">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in _sessions)
                    {
                        var isCurrentSession = session == _sessions.FirstOrDefault();
                        <tr>
                            <td>
                                @session.Device
                                @if (isCurrentSession)
                                {
                                    <span class="badge bg-info ms-1">Current</span>
                                }
                            </td>
                            <td>@session.Location</td>
                            <td>@session.LastActive.ToString("g")</td>
                            <td>
                                @if (!isCurrentSession)
                                {
                                    <button class="btn btn-outline-danger btn-sm"
                                            @onclick="() => _sessionToRevoke = session">
                                        Revoke
                                    </button>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    </div>

    <RevokeSessionDialog Session="_sessionToRevoke"
                         OnConfirm="ConfirmRevoke"
                         OnCancel="() => _sessionToRevoke = null" />
}

@code {
    private SecuritySettings? _settings;
    private List<ActiveSession> _sessions = [];
    private bool _twoFactorEnabled;
    private ActiveSession? _sessionToRevoke;
    private string? _statusMessage;
    private bool _isError;

    protected override async Task OnInitializedAsync()
    {
        await LoadSettings();
    }

    private async Task LoadSettings()
    {
        _settings = await SettingsService.GetSecuritySettingsAsync();
        _sessions = _settings.Sessions.ToList();
        _twoFactorEnabled = _settings.TwoFactorEnabled;
    }

    private async Task HandleChangePassword((string CurrentPassword, string NewPassword) args)
    {
        await SettingsService.ChangePasswordAsync(args.CurrentPassword, args.NewPassword);
    }

    private async Task ConfirmRevoke()
    {
        if (_sessionToRevoke is null) return;

        try
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            _sessions.Remove(_sessionToRevoke);
            _statusMessage = $"Session on \"{_sessionToRevoke.Device}\" has been revoked.";
            _isError = false;
        }
        catch (Exception ex)
        {
            _statusMessage = $"Failed to revoke session: {ex.Message}";
            _isError = true;
        }
        finally
        {
            _sessionToRevoke = null;
        }
    }
}
", "path": "/tmp/sv-808687ea18c2457cae0279030669c6e5/Components/Pages/Settings/SecuritySection.razor"}

{"file_text": "@using sv_808687ea18c2457cae0279030669c6e5.Services
@inject ISettingsService SettingsService

<h4 class="mb-4">Appearance</h4>

@if (_settings is null)
{
    <p class="text-muted">Loading appearance settings…</p>
}
else
{
    @if (_statusMessage is not null)
    {
        <div class="alert alert-success alert-dismissible" role="alert">
            @_statusMessage
            <button type="button" class="btn-close" @onclick="() => _statusMessage = null"></button>
        </div>
    }

    <div class="row">
        <div class="col-md-7">
            <div class="mb-4">
                <h6>Theme</h6>
                @foreach (var theme in new[] { "Light", "Dark", "System" })
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="theme" id="@($"theme-{theme}")"
                               value="@theme" checked="@(_theme == theme)"
                               @onchange="() => _theme = theme" />
                        <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                    </div>
                }
            </div>

            <div class="mb-4">
                <h6>Font Size</h6>
                @foreach (var size in new[] { "Small", "Medium", "Large" })
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="fontSize" id="@($"fs-{size}")"
                               value="@size" checked="@(_fontSize == size)"
                               @onchange="() => _fontSize = size" />
                        <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                    </div>
                }
            </div>

            <div class="mb-4">
                <h6>Language</h6>
                <select class="form-select" style="max-width: 250px;" @bind="_language">
                    <option value="en">English</option>
                    <option value="es">Español</option>
                    <option value="fr">Français</option>
                    <option value="de">Deutsch</option>
                    <option value="ja">日本語</option>
                    <option value="zh">中文</option>
                </select>
            </div>

            <div class="mb-4">
                <h6>Compact Mode</h6>
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" role="switch" id="compactMode"
                           checked="@_compactMode"
                           @onchange="e => _compactMode = (bool)e.Value!" />
                    <label class="form-check-label" for="compactMode">Enable compact mode</label>
                </div>
            </div>

            <button class="btn btn-primary" @onclick="SaveSettings" disabled="@_isSaving">
                @(_isSaving ? "Saving…" : "Save")
            </button>
        </div>

        <div class="col-md-5">
            <h6>Live Preview</h6>
            <div class="preview-container border rounded p-3 @PreviewThemeClass" style="@PreviewFontStyle">
                <div class="preview-header d-flex justify-content-between align-items-center mb-2"
                     style="@(_compactMode ? "padding: 0.25rem 0;" : "padding: 0.5rem 0;")">
                    <strong>Sample Dashboard</strong>
                    <span class="badge @PreviewBadgeClass">Active</span>
                </div>
                <p class="mb-2" style="@(_compactMode ? "margin-bottom: 0.25rem !important;" : "")">
                    This is how your content will look with the selected settings.
                </p>
                <div class="d-flex gap-2 flex-wrap" style="@(_compactMode ? "gap: 0.25rem !important;" : "")">
                    <button class="btn btn-sm @PreviewButtonClass">Primary</button>
                    <button class="btn btn-sm @PreviewButtonOutlineClass">Secondary</button>
                </div>
                <hr style="@(_compactMode ? "margin: 0.5rem 0;" : "")" />
                <small class="@PreviewMutedClass">
                    Language: @GetLanguageLabel(_language) · Compact: @(_compactMode ? "On" : "Off")
                </small>
            </div>
        </div>
    </div>
}

@code {
    private AppearanceSettings? _settings;
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;
    private string? _statusMessage;
    private bool _isSaving;

    protected override async Task OnInitializedAsync()
    {
        _settings = await SettingsService.GetAppearanceAsync();
        _theme = _settings.Theme;
        _fontSize = _settings.FontSize;
        _language = _settings.Language;
        _compactMode = _settings.CompactMode;
    }

    private async Task SaveSettings()
    {
        _isSaving = true;
        try
        {
            var updated = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
            await SettingsService.SaveAppearanceAsync(updated);
            _settings = updated;
            _statusMessage = "Appearance settings saved!";
        }
        finally
        {
            _isSaving = false;
        }
    }

    private string PreviewFontStyle => _fontSize switch
    {
        "Small" => "font-size: 0.8rem;",
        "Large" => "font-size: 1.15rem;",
        _ => "font-size: 0.95rem;"
    };

    private bool IsDark => _theme == "Dark";

    private string PreviewThemeClass => IsDark
        ? "bg-dark text-light"
        : "bg-white text-dark";

    private string PreviewBadgeClass => IsDark ? "bg-light text-dark" : "bg-success";
    private string PreviewButtonClass => IsDark ? "btn-light" : "btn-primary";
    private string PreviewButtonOutlineClass => IsDark ? "btn-outline-light" : "btn-outline-secondary";
    private string PreviewMutedClass => IsDark ? "text-light opacity-75" : "text-muted";

    private static string GetLanguageLabel(string code) => code switch
    {
        "en" => "English",
        "es" => "Español",
        "fr" => "Français",
        "de" => "Deutsch",
        "ja" => "日本語",
        "zh" => "中文",
        _ => code
    };
}
